1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type Result = QuoteResult | ClaimResult;
41	
42	export interface QuoteResult {
43	  premium: number;
44	}
45	
46	export interface ClaimResult {
47	  payout: number;
48	  remainingCap: number;
49	}
50	
51	export interface ScenarioResult {
52	  results: Result[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
57	// Base premium for a single item of each type.
58	const UNIT_BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	// Insurance value of a single item of each type.
68	const UNIT_INSURANCE_VALUES: Record<string, number> = {
69	  sword: 1000,
70	  amulet: 600,
71	  staff: 800,
72	  potion: 400,
73	  rune: 250,
74	  moonstone: 250,
75	};
76	
77	const LOYALTY_YEARS_THRESHOLD = 2;
78	const LOYALTY_DISCOUNT_RATE = 2 / 10;
79	const FOLLOW_UP_DISCOUNT_RATE = 15 / 100;
80	const CURSE_SURCHARGE_RATE = 1 / 2;
81	const HIGH_ENCHANTMENT_THRESHOLD = 5;
82	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 3 / 10;
83	const BLOCK_SIZE = 3;
84	const BLOCK_BASE_PREMIUM = 60;
85	const DEDUCTIBLE = 100;
86	const CAP_MULTIPLIER = 2;
87	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
88	const REDUCED_REIMBURSEMENT_RATE = 1 / 2;
89	
90	const unitBasePremium = (type: string): number => UNIT_BASE_PREMIUMS[type];
91	
92	const countByType = (items: Item[]): Map<string, number> =>
93	  items.reduce(
94	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
95	    new Map<string, number>(),
96	  );
97	
98	// A building block of 3 alike components is offered at a special base premium.
99	const basePremiumForItemGroup = (type: string, count: number): number =>
100	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * unitBasePremium(type);
101	
102	const policyBasePremium = (items: Item[]): number =>
103	  [...countByType(items)].reduce(
104	    (total, [type, count]) => total + basePremiumForItemGroup(type, count),
105	    0,
106	  );
107	
108	// Premium-side enchantment rule (threshold 5), distinct from the claim-side
109	// reduced-reimbursement rule (threshold 8).
110	const qualifiesForHighEnchantmentSurcharge = (item: Item): boolean =>
111	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
112	
113	const surchargeRate = (item: Item): number =>
114	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
115	  (qualifiesForHighEnchantmentSurcharge(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
116	
117	// Item-specific modifiers apply to the affected item's own base premium, i.e.
118	// the unit price of its type — a block discount never shrinks a surcharge.
119	const itemSurcharge = (item: Item): number =>
120	  unitBasePremium(item.type) * surchargeRate(item);
121	
122	const itemSurcharges = (items: Item[]): number =>
123	  items.reduce((total, item) => total + itemSurcharge(item), 0);
124	
125	const isLongStanding = (customer: Customer): boolean =>
126	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
127	
128	// Policy-wide modifiers apply to the policy base premium only — never to the
129	// item surcharges. Net signed delta: a discount can outweigh the surcharge.
130	// Every quote is a first insurance for its items, regardless of customer
131	// history, so that surcharge always applies.
132	const policyAdjustmentRate = (
133	  customer: Customer,
134	  isFollowUpContract: boolean,
135	): number =>
136	  FIRST_INSURANCE_SURCHARGE_RATE -
137	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
138	  (isFollowUpContract ? FOLLOW_UP_DISCOUNT_RATE : 0);
139	
140	// Premiums round up, in the MHPCO's favour. The adjustment is added as a
141	// separate term rather than folded into a `base * 1.1` factor, which is not
142	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
143	const quotePremium = (
144	  items: Item[],
145	  customer: Customer,
146	  isFollowUpContract: boolean,
147	): number => {
148	  const base = policyBasePremium(items);
149	  return Math.ceil(
150	    base +
151	      itemSurcharges(items) +
152	      base * policyAdjustmentRate(customer, isFollowUpContract) +
153	      PROCESSING_FEE,
154	  );
155	};
156	
157	const unitInsuranceValue = (type: string): number =>
158	  UNIT_INSURANCE_VALUES[type];
159	
160	// The total payout per policy is capped at twice the insurance sum. Premium
161	// modifiers never reach the insurance sum: it is the plain sum of the unit
162	// values of the insured items.
163	const insuranceSum = (items: Item[]): number =>
164	  items.reduce((sum, item) => sum + unitInsuranceValue(item.type), 0);
165	
166	// A policy created by a quote step, tracked so later claims can pay out
167	// against it. `remainingCap` shrinks as successive claims are settled.
168	interface Policy {
169	  items: Item[];
170	  remainingCap: number;
171	}
172	
173	const openPolicy = (items: Item[]): Policy => ({
174	  items,
175	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
176	});
177	
178	// State accumulated by the steps run so far. Later steps price and pay out
179	// against what earlier steps established, so each step reads the state it was
180	// run with and returns the state the next step should see.
181	interface ScenarioState {
182	  customer: Customer;
183	  contractsSoFar: number;
184	  // Keyed by the zero-based index of the quote step that created the policy.
185	  policies: Map<number, Policy>;
186	}
187	
188	// A step's outcome: what to report, and how the scenario stands afterwards.
189	interface StepOutcome {
190	  result: Result;
191	  state: ScenarioState;
192	}
193	
194	// Records a policy against the step index that identifies it, leaving the
195	// state it was given untouched.
196	const withPolicy = (
197	  state: ScenarioState,
198	  policyId: number,
199	  policy: Policy,
200	): ScenarioState => ({
201	  ...state,
202	  policies: new Map(state.policies).set(policyId, policy),
203	});
204	
205	const quote = (
206	  step: QuoteStep,
207	  state: ScenarioState,
208	  stepIndex: number,
209	): StepOutcome => ({
210	  result: {
211	    premium: quotePremium(step.items, state.customer, state.contractsSoFar > 0),
212	  },
213	  state: withPolicy(
214	    { ...state, contractsSoFar: state.contractsSoFar + 1 },
215	    stepIndex,
216	    openPolicy(step.items),
217	  ),
218	});
219	
220	// Claim-side enchantment rule (threshold 8), distinct from the premium-side
221	// high-enchantment surcharge (threshold 5).
222	const qualifiesForReducedReimbursement = (item: Item): boolean =>
223	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_THRESHOLD;
224	
225	// Damage to heavily enchanted items is reimbursed at 50 % of the damage amount.
226	const reimbursementRate = (item: Item): number =>
227	  qualifiesForReducedReimbursement(item) ? REDUCED_REIMBURSEMENT_RATE : 1;
228	
229	// A damage entry together with the specific insured item it was matched to.
230	interface MatchedDamage {
231	  damage: Damage;
232	  item: Item;
233	}
234	
235	// What a single damage entry entitles the claimant to, before the policy-wide
236	// cap is applied. A deductible applies per damage event, i.e. once per damaged
237	// item. Special clauses reduce the reimbursement first; the deductible comes
238	// off after.
239	const damageEntitlement = ({ damage, item }: MatchedDamage): number =>
240	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
241	
242	// Pairs each damage entry with a distinct insured item of the same type: two
243	// damages to "sword" refer to two different insured swords, not the same one
244	// twice. Instances of a type are consumed in the order they were insured.
245	const matchDamagesToItems = (
246	  insuredItems: Item[],
247	  damages: Damage[],
248	): MatchedDamage[] => {
249	  const unclaimed = [...insuredItems];
250	  return damages.map((damage) => {
251	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
252	    if (index === -1) {
253	      throw new Error(
254	        `the policy does not cover a damaged ${damage.itemType}`,
255	      );
256	    }
257	    return { damage, item: unclaimed.splice(index, 1)[0] };
258	  });
259	};
260	
261	const claim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
262	  const policy = state.policies.get(step.policy)!;
263	  const matchedDamages = matchDamagesToItems(policy.items, step.incident.damages);
264	  const desiredPayout = matchedDamages.reduce(
265	    (total, matched) => total + damageEntitlement(matched),
266	    0,
267	  );
268	  // The total payout per policy is capped; a claim gets at most what is left.
269	  const payout = Math.min(desiredPayout, policy.remainingCap);
270	  const remainingCap = policy.remainingCap - payout;
271	  return {
272	    result: { payout, remainingCap },
273	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
274	  };
275	};
276	
277	const runStep = (
278	  step: Step,
279	  state: ScenarioState,
280	  stepIndex: number,
281	): StepOutcome => {
282	  switch (step.op) {
283	    case "quote":
284	      return quote(step, state, stepIndex);
285	    case "claim":
286	      return claim(step, state);
287	  }
288	};
289	
290	export const runScenario = (scenario: Scenario): ScenarioResult => {
291	  const initialState: ScenarioState = {
292	    customer: scenario.customer,
293	    contractsSoFar: 0,
294	    policies: new Map(),
295	  };
296	  const { results } = scenario.steps.reduce<{
297	    results: Result[];
298	    state: ScenarioState;
299	  }>(
300	    ({ results, state }, step, stepIndex) => {
301	      const outcome = runStep(step, state, stepIndex);
302	      return { results: [...results, outcome.result], state: outcome.state };
303	    },
304	    { results: [], state: initialState },
305	  );
306	  return { results };
307	};
